#include "DataManager.hpp"
#include "EventBus.hpp"
#include "Application.hpp"
#include "platform/LogShim.h"
#include <algorithm>
#include <new>

static constexpr const char* TAG = "DataManager";
#ifdef ESP_PLATFORM
#include "types/FrameworkSecureClient.hpp"
#include "lwip/dns.h"
#include "lwip/ip_addr.h"
